<?php
declare(strict_types=1);namespace Nexus\Features\Perfil\Application;use Nexus\Features\Perfil\Domain\AlmacenImagen;use Nexus\Features\Perfil\Domain\FotoPerfilRepository;use Nexus\Shared\Domain\ValueObject\Cedula;use Nexus\Shared\DomainException;
final class FotoPerfilService{private FotoPerfilRepository $repo;private AlmacenImagen $almacen;public function __construct(FotoPerfilRepository $r,AlmacenImagen $a){$this->repo=$r;$this->almacen=$a;}public function cambiar(Cedula $c,?array $archivo):string{if($archivo===null)throw new DomainException('Debe enviar un archivo de foto.');$anterior=$this->repo->fotoActual($c);if($anterior===null)throw new DomainException('No existe el usuario indicado.',404);$nuevo=$this->almacen->almacenar($archivo);try{$this->repo->guardar($c,$nuevo);}catch(\Throwable $e){$this->almacen->eliminarAnterior($nuevo);throw $e;}$this->almacen->eliminarAnterior($anterior);return 'uploads/perfiles/'.$nuevo;}}
